// WPForm 29710 — full ContactForm with WPForms meta capture
const raw = $json.body || $json;
const crypto = require('crypto');
const entryId = String(raw.entry_id || raw.entry?.entry_id || raw.id || '');
const hash = crypto.createHash('sha256').update(`29710:${entryId}`).digest('hex');

// WPForms Webhooks Addon may put meta at various locations — pick defensively
function pickMeta(obj, keys) {
  for (const k of keys) {
    const parts = k.split('.');
    let v = obj;
    for (const p of parts) v = v?.[p];
    if (v !== undefined && v !== null && v !== '') return String(v);
  }
  return '';
}
const pageUrl   = pickMeta(raw, ['meta.url','meta.page_url','url','page_url','referer_source','entry.url','entry.page_url']);
const referer   = pickMeta(raw, ['meta.referer','meta.referrer','referer','referrer','entry.referer','headers.referer']);
const userIp    = pickMeta(raw, ['meta.user_ip','meta.ip','user_ip','ip','entry.user_ip','entry.ip']);
const userAgent = pickMeta(raw, ['meta.user_agent','meta.useragent','user_agent','useragent','entry.user_agent']);

return [{ json: {
  source: 'wpform_29710',
  WPFormName: 'ContactForm',
  wpformsEntryId: entryId,
  Idempotency_Hash__c: hash,
  Received_At__c: new Date().toISOString(),
  Payload__c: JSON.stringify(raw).substring(0, 32000),
