  fbc:           raw.fields?.['18'] || raw.field18 || '',
  fbp:           raw.fields?.['19'] || raw.field19 || '',
  msclkid:       raw.fields?.['20'] || raw.field20 || '',
  ROIcalculator: raw.fields?.['26'] || raw.field26 || '',
